   284	            // Configured (non-Idle, interval-bound) market whose strike report
   285	            // disagrees with the selected interval-open. This is a fail-closed
   286	            // anomaly — the strike feed is reporting for the wrong window — and
   287	            // must be observable rather than a silent drop. Record it and warn;
   288	            // `price_to_beat` is left untouched so entry stays fail-closed.
   289	            self.resolution_strike_window_mismatch_count = self
   290	                .resolution_strike_window_mismatch_count
   291	                .saturating_add(1);
   292	            log::warn!(
   293	                "binary_oracle_edge_taker resolution-strike window mismatch (fail-closed): market_id={:?} window_open_ms={} interval_start_ms={} strike={} — strike rejected, price_to_beat unchanged",
   294	                self.market_id,
   295	                window_open_ms,
   296	                interval_start_ms,
   297	                strike,
   298	            );
   299	            return;
   300	        }
   301	        if !is_positive_finite(strike) {
   302	            return;
   303	        }
